	if r == 0x270F { return true }
	if r == 0x2712 || r == 0x2714 || r == 0x2716 || r == 0x271D || r == 0x2721 { return true }
	if r == 0x2728 { return true }
	if r >= 0x2733 && r <= 0x2734 { return true }
	if r == 0x2744 || r == 0x2747 || r == 0x274C || r == 0x274E { return true }
	if r >= 0x2753 && r <= 0x2755 { return true }
	if r == 0x2757 { return true }
