def get_section_pattern(ext):
    if ext in ('.go', '.ts', '.tsx', '.js', '.jsx', '.cs'):
        start = re.compile(r'^(\s*//\s*#region\s+)(🔖)(.+?)(\s*)$')
        end = re.compile(r'^(\s*//\s*#endregion\s+)(🔖)(.+?)(\s*)$')
        return start, end
    elif ext in ('.py', '.rb'):
        start = re.compile(r'^(\s*#\s*#?region\s+)(🔖)(.+?)(\s*)$')
        end = re.compile(r'^(\s*#\s*#?endregion\s+)(🔖)(.+?)(\s*)$')
        return start, end
    elif ext == '.rs':
        start = re.compile(r'^(.+//\s*)(🔖)(.+?)(\s*)$')
        end = re.compile(r'^(.+//\s*)(🔖)(.+?)(\s*)$')
        return start, end
    elif ext == '.sql':
        start = re.compile(r'^(\s*--\s*#region\s+)(🔖)(.+?)(\s*)$')
        end = re.compile(r'^(\s*--\s*#endregion\s+)(🔖)(.+?)(\s*)$')
        return start, end
    return None, None

def process_file(filepath):
    ext = os.path.splitext(filepath)[1].lower()
    start_pat, end_pat = get_section_pattern(ext)
    if not start_pat:
        return False
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except (UnicodeDecodeError, IOError):
        return False

    sections = []
    stack = []
    for i, line in enumerate(lines):
        m = start_pat.match(line)
        if m:
            name = m.group(3).strip()
            sections.append((i, 'start', name, len(stack)))
            stack.append(name)
        else:
            m = end_pat.match(line)
            if m:
                if stack:
                    stack.pop()

    if not sections:
        return False

    sibling_groups = {}
    stack = []
    for (idx, kind, name, depth) in sections:
        if kind == 'start':
            parent_key = tuple(stack)
            group_key = (depth, parent_key)
            if group_key not in sibling_groups:
                sibling_groups[group_key] = []
            if name not in sibling_groups[group_key]:
                sibling_groups[group_key].append(name)
            stack.append(name)

    name_emoji = {}
    for group_key, names in sibling_groups.items():
        base_offset = abs(hash(str(group_key))) % len(EMOJI_POOL)
        for i, name in enumerate(names):
            emoji_idx = (base_offset + i) % len(EMOJI_POOL)
            full_path = group_key[1] + (name,)
            used = set(name_emoji.get(group_key[1] + (n,), '') for n in names[:i])
            while EMOJI_POOL[emoji_idx] in used:
                emoji_idx = (emoji_idx + 1) % len(EMOJI_POOL)
            name_emoji[full_path] = EMOJI_POOL[emoji_idx]

    stack = []
    modified = False
    new_lines = []

    for i, line in enumerate(lines):
        m = start_pat.match(line)
        if m:
            name = m.group(3).strip()
            parent_key = tuple(stack)
            full_path = parent_key + (name,)
            emoji = name_emoji.get(full_path, '🔖')
            new_line = m.group(1) + emoji + m.group(3) + m.group(4)
            if not new_line.endswith('\n') and line.endswith('\n'):
                new_line += '\n'
            new_lines.append(new_line)
            stack.append(name)
            if emoji != '🔖':
                modified = True
        else:
            m = end_pat.match(line)
            if m:
                name = m.group(3).strip()
                if stack and stack[-1] == name:
                    parent_key = tuple(stack[:-1])
                    full_path = parent_key + (name,)
                    emoji = name_emoji.get(full_path, '🔖')
                    stack.pop()
                else:
                    emoji = '🔖'
                    if stack:
                        stack.pop()
                new_line = m.group(1) + emoji + m.group(3) + m.group(4)
                if not new_line.endswith('\n') and line.endswith('\n'):
                    new_line += '\n'
                new_lines.append(new_line)
                if emoji != '🔖':
                    modified = True
            else:
                new_lines.append(line)

    if modified:
        with open(filepath, 'w', encoding='utf-8') as f:
            f.writelines(new_lines)
        return True
    return False

root = '/workspaces/semio'
count = 0
for dirpath, dirs, files in os.walk(root):
    dirs[:] = [d for d in dirs if d not in ['node_modules', '.git', 'target', '.repo', '__pycache__', 'dist', 'build', 'coverage', 'storybook-static']]
    for fname in files:
        ext = os.path.splitext(fname)[1].lower()
        if ext in ('.go', '.ts', '.tsx', '.js', '.jsx', '.py', '.cs', '.rs', '.sql', '.rb'):
            filepath = os.path.join(dirpath, fname)
            if process_file(filepath):
                count += 1
                rel = os.path.relpath(filepath, root)
                print(f'Updated: {rel}')

print(f'\\nTotal files updated: {count}')
