import re, os, unicodedata

def is_emoji_cp(cp):
    return (
        0x1F600 <= cp <= 0x1F64F or 0x1F300 <= cp <= 0x1F5FF or
        0x1F680 <= cp <= 0x1F6FF or 0x1F900 <= cp <= 0x1F9FF or
        0x1FA00 <= cp <= 0x1FAFF or 0x2600 <= cp <= 0x26FF or
        0x2700 <= cp <= 0x27BF or 0x2300 <= cp <= 0x23FF or
        0x2B50 <= cp <= 0x2B55 or cp == 0x200D or 0xFE00 <= cp <= 0xFE0F or
        cp in (0x203C, 0x2049, 0x20E3, 0x00A9, 0x00AE, 0x2122, 0x2139) or
        0x2194 <= cp <= 0x2199 or 0x21A9 <= cp <= 0x21AA or
        0x231A <= cp <= 0x231B or 0x25AA <= cp <= 0x25FE or
        unicodedata.category(chr(cp)).startswith('So')
    )

def starts_emoji(t):
    return bool(t) and is_emoji_cp(ord(t[0]))

# Check key compose files
files = {
    'compose/js/index.ts': '.ts',
    'compose/py/main.py': '.py',
    'compose/rs/lib.rs': '.rs',
    'compose/net/Compose/Compose.cs': '.cs',
    'compose/go/main.go': '.go',
}

for fpath, ext in files.items():
    full = os.path.join('/workspaces/semio', fpath)
    if not os.path.exists(full):
        print(f'{fpath}: NOT FOUND')
        continue
    with open(full, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()

    with_emoji = 0
    without_emoji = 0

    if ext == '.go':
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^(type|func|var|const)\s', stripped):
                if i > 0 and lines[i-1].strip().startswith('//'):
                    doc = re.sub(r'^//\s*', '', lines[i-1].strip())
                    if starts_emoji(doc):
                        with_emoji += 1
                    elif doc and not doc.startswith('go:'):
                        without_emoji += 1
    elif ext == '.ts':
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^\s*(?:export\s+)?(?:async\s+)?(?:function|class|interface|type|const|let|var|enum)\s+\w+', stripped):
                if i > 0:
                    prev = lines[i-1].strip()
                    if prev.startswith('//') or prev.startswith('* ') or prev == '*/':
                        doc = re.sub(r'^(?://|/?\*+)\s*', '', prev)
                        if starts_emoji(doc):
                            with_emoji += 1
                        elif doc and doc not in ('/', '*'):
                            without_emoji += 1
    elif ext == '.py':
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^\s*(def|class)\s+\w+', stripped):
                # Check for docstring below
                j = i + 1
                while j < len(lines) and lines[j].strip() == '':
                    j += 1
                if j < len(lines) and ('\"\"\"' in lines[j] or \"'''\" in lines[j]):
                    doc = re.sub(r'^\\s*(?:\"\"\"|\\'\\'\\')\\s*', '', lines[j].strip())
                    if starts_emoji(doc):
                        with_emoji += 1
                    elif doc:
                        without_emoji += 1
    elif ext == '.rs':
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^\s*(?:pub\s+)?(?:fn|struct|enum|trait|impl|const|static|type|mod)\s+\w+', stripped):
                if i > 0 and lines[i-1].strip().startswith('///'):
                    doc = re.sub(r'^///\s*', '', lines[i-1].strip())
                    if starts_emoji(doc):
                        with_emoji += 1
                    elif doc:
                        without_emoji += 1
    elif ext == '.cs':
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^\s*(?:public|private|protected|internal)', stripped):
                # Check for XML doc above
                j = i - 1
                while j >= 0 and (lines[j].strip().startswith('///') or lines[j].strip().startswith('[')):
                    j -= 1
                j += 1
                has_doc = any(lines[k].strip().startswith('///') for k in range(j, i))
                if has_doc:
                    for k in range(j, i):
                        if '<summary>' in lines[k]:
                            doc = re.sub(r'.*<summary>\s*', '', lines[k].strip())
                            doc = re.sub(r'\s*</summary>.*', '', doc)
                            if starts_emoji(doc):
                                with_emoji += 1
                            elif doc:
                                without_emoji += 1
                            break

    print(f'{fpath}: {with_emoji} with emoji, {without_emoji} missing')
"

