    """Extract emoji prefix from a string"""
    if not text:
        return '', text
    # Match leading emoji (1-4 chars that are emoji) followed by space
    m = re.match(r'^([\U0001F300-\U0001FFFF\u2600-\u27FF\u2700-\u27BF\u2300-\u23FF\u2190-\u21FF\u25A0-\u25FF\u2B00-\u2BFF\U0001F900-\U0001F9FF\U0001FA00-\U0001FA6F\U0001FA70-\U0001FAFF]+)\s*', text)
    if m:
        return m.group(1), text[m.end():]
    return '', text

